//! Compares the config loader with what the original Go deej produced for the same files.
//!
//! `testdata/golden/config-upstream.json` and `config-fork.json` are generated by `tools/golden-gen` from the
//! real viper/yaml/cast libraries. Settings both versions understand must match upstream; fork-only settings
//! must match the fork. The deliberate differences (COMPATIBILITY_MATRIX C10, C12, C13) are listed explicitly
//! in `expected_mapping_override` so they can't hide other mismatches.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use deej_core::config::{self, NoiseReduction, Severity};
use serde_json::Value;

fn testdata() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../testdata")
}

fn golden(variant: &str) -> Vec<Value> {
    let path = testdata().join(format!("golden/config-{variant}.json"));
    serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap()
}

fn load_fixture(file: &str) -> Result<config::Loaded, config::ConfigError> {
    let dir = testdata().join("configs");
    let source = std::fs::read_to_string(dir.join(file)).unwrap();
    let prefs = std::fs::read_to_string(dir.join(file.replace(".yaml", ".preferences.yaml"))).ok();
    config::parse(&source, prefs.as_deref())
}

fn mapping_from_json(value: &Value) -> BTreeMap<usize, Vec<String>> {
    let mut result = BTreeMap::new();
    if let Some(map) = value.as_object() {
        for (key, targets) in map {
            let targets = targets.as_array().unwrap().iter().map(|t| t.as_str().unwrap().to_string()).collect();
            result.insert(key.parse().unwrap(), targets);
        }
    }
    result
}

/// Fixtures where deej Next intentionally differs from upstream's slider mapping.
fn expected_mapping_override(file: &str) -> Option<BTreeMap<usize, Vec<String>>> {
    let m = |entries: &[(usize, &[&str])]| -> BTreeMap<usize, Vec<String>> {
        entries.iter().map(|(k, v)| (*k, v.iter().map(|s| s.to_string()).collect())).collect()
    };

    match file {
        // C13: "foo", "1.5" and "-1" are ignored instead of landing on slider 0 / -1. "01" is still slider 1
        "04_badkeys.yaml" => Some(m(&[(1, &["a.exe"])])),
        // C10: boolean words used as targets stay literal (upstream turned both into "false")
        "26_no.yaml" => Some(m(&[(0, &["no"]), (1, &["off"])])),
        // C13: the quoted key " 4" isn't an index (upstream: slider 0)
        "49_key_forms.yaml" => Some(m(&[(3, &["b.exe"]), (5, &["d.exe"]), (9, &["a.exe"])])),
        _ => None,
    }
}

#[test]
fn matches_upstream_deej_for_shared_settings() {
    let upstream = golden("upstream");
    assert!(upstream.len() >= 50, "golden file looks incomplete");

    for case in &upstream {
        let file = case["file"].as_str().unwrap();
        let ours = load_fixture(file);

        if case.get("error").is_some() {
            assert!(ours.is_err(), "{file}: upstream failed to load it, we didn't: {:?}", ours.map(|l| l.config));
            continue;
        }

        let loaded = ours.unwrap_or_else(|e| panic!("{file}: upstream loads it, we failed: {e}"));
        let c = &loaded.config;

        let expected_mapping = expected_mapping_override(file).unwrap_or_else(|| {
            assert!(
                case.get("nondeterministic_mapping").is_none(),
                "{file}: upstream's result is random here; add an explicit expectation"
            );
            mapping_from_json(&case["slider_mapping"])
        });

        assert_eq!(c.slider_mapping, expected_mapping, "{file}: slider_mapping");
        assert_eq!(c.invert_sliders, case["invert_sliders"].as_bool().unwrap(), "{file}: invert_sliders");
        assert_eq!(c.com_port, case["com_port"].as_str().unwrap(), "{file}: com_port");
        assert_eq!(i64::from(c.baud_rate), case["baud_rate"].as_i64().unwrap(), "{file}: baud_rate");
        assert_eq!(
            c.noise_reduction,
            NoiseReduction::from_config(case["noise_reduction"].as_str().unwrap()),
            "{file}: noise_reduction"
        );
    }
}

#[test]
fn matches_the_fork_for_fork_only_settings() {
    for case in &golden("fork") {
        let file = case["file"].as_str().unwrap();
        let Ok(loaded) = load_fixture(file) else { continue };
        let c = &loaded.config;

        let exclude: Vec<String> = case
            .get("unmapped_exclude")
            .and_then(Value::as_array)
            .map(|a| a.iter().map(|s| s.as_str().unwrap().to_string()).collect())
            .unwrap_or_default();
        assert_eq!(c.unmapped_exclude, exclude, "{file}: unmapped_exclude");

        let Some(sens) = case.get("slider_sensitivity") else { continue };

        let pair = |v: &Value| (v.get("curve").and_then(Value::as_f64), v.get("max_volume").and_then(Value::as_f64));
        let ours = |o: &config::SensitivityOverride| (o.curve, o.max_volume);

        assert_eq!(ours(&c.slider_sensitivity.default), pair(&sens["default"]), "{file}: sensitivity default");

        let expected: BTreeMap<usize, _> =
            sens["overrides"].as_object().unwrap().iter().map(|(k, v)| (k.parse().unwrap(), pair(v))).collect();
        let actual: BTreeMap<usize, _> = c.slider_sensitivity.sliders.iter().map(|(k, v)| (*k, ours(v))).collect();
        assert_eq!(actual, expected, "{file}: sensitivity overrides");

        let warnings = loaded
            .diagnostics
            .iter()
            .filter(|d| d.severity == Severity::Warning && d.key.starts_with("slider_sensitivity"))
            .count();
        assert_eq!(warnings as u64, sens["error_count"].as_u64().unwrap(), "{file}: sensitivity problems reported");
    }
}

#[test]
fn every_fixture_has_golden_data() {
    let upstream = golden("upstream");
    let names: Vec<&str> = upstream.iter().map(|c| c["file"].as_str().unwrap()).collect();

    for entry in std::fs::read_dir(testdata().join("configs")).unwrap() {
        let name = entry.unwrap().file_name().into_string().unwrap();
        if name.ends_with(".yaml") && !name.ends_with(".preferences.yaml") {
            assert!(names.contains(&name.as_str()), "{name} has no golden data; run tools/golden-gen/gen.sh");
        }
    }
}
